/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 *     constructor(val?: number, next?: ListNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.next = (next===undefined ? null : next)
 *     }
 * }
 */

function sortList(head: ListNode | null): ListNode | null {
  // Пустой список или один узел уже отсортированы
  if (!head || !head.next) return head;

  // Ищем середину: fast стартует на шаг впереди,
  // поэтому для чётной длины slow остановится на конце левой половины
  let slow: ListNode = head;
  let fast: ListNode | null = head.next;
  while (fast && fast.next) {
    slow = slow.next!;
    fast = fast.next.next;
  }

  // Разрезаем список на две половины
  const right = slow.next;
  slow.next = null;

  // Сортируем половины рекурсивно и сливаем
  return merge(sortList(head), sortList(right));
}

// Слияние двух отсортированных списков
function merge(a: ListNode | null, b: ListNode | null): ListNode | null {
  // Фиктивная голова избавляет от особого случая для первого узла
  const dummy = new ListNode(0);
  let tail = dummy;

  while (a && b) {
    // Берём меньший узел (при равенстве — из a, сортировка устойчива)
    if (a.val <= b.val) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next;
  }

  // Остаток одного из списков уже отсортирован — пришиваем целиком
  tail.next = a ?? b;
  return dummy.next;
}

// Время: O(n log n) — log n уровней разбиения, на каждом слияние за O(n)
// Память: O(log n) — глубина рекурсии (узлы не копируются)
